		// if one of the keys has no host (i.e. is a catch-all for
		// any hostname), then we need to null out the host matcher
		// entirely so that it matches all hosts
		if addr.Host == "" && !catchAllHosts {
			chosenMatcherPair.hostm = nil
			catchAllHosts = true
		}
		if catchAllHosts {
			continue
		}

		// add this server block's keys to the matcher
		// pair if it doesn't already exist
		if addr.Host != "" {
			var found bool
			for _, h := range chosenMatcherPair.hostm {
				if h == addr.Host {
					found = true
					break
				}
			}
			if !found {
				chosenMatcherPair.hostm = append(chosenMatcherPair.hostm, addr.Host)
			}
		}
	}

	// iterate each pairing of host and path matchers and
	// put them into a map for JSON encoding
	var matcherSets []map[string]caddyhttp.RequestMatcher
	for _, mp := range matcherPairs {
		matcherSet := make(map[string]caddyhttp.RequestMatcher)
		if len(mp.hostm) > 0 {
			matcherSet["host"] = mp.hostm
		}
		if len(mp.pathm) > 0 {
			matcherSet["path"] = mp.pathm
		}
		if len(matcherSet) > 0 {
			matcherSets = append(matcherSets, matcherSet)
		}
	}

	// finally, encode each of the matcher sets
	matcherSetsEnc := make([]caddy.ModuleMap, 0, len(matcherSets))
	for _, ms := range matcherSets {
		msEncoded, err := encodeMatcherSet(ms)
		if err != nil {
			return nil, fmt.Errorf("server block %v: %v", sblock.block.Keys, err)
		}
		matcherSetsEnc = append(matcherSetsEnc, msEncoded)
	}

	return matcherSetsEnc, nil
}

func parseMatcherDefinitions(d *caddyfile.Dispenser, matchers map[string]caddy.ModuleMap) error {
	d.Next() // advance to the first token

	definitionName := d.Val()
	if _, ok := matchers[definitionName]; ok {
		return fmt.Errorf("matcher is defined more than once: %s", definitionName)
	}
	matchers[definitionName] = make(caddy.ModuleMap)
	matcherLabel := definitionName[1:]

	if d.NextArg() {
		currentToken := d.Token()
		if currentToken.Quoted() {
			expressionToken := caddyfile.Token{
				Text: "expression",
				File: d.File(),
				Line: d.Line(),
			}
			exprDispenser := caddyfile.NewDispenser([]caddyfile.Token{expressionToken, currentToken})
			exprDispenser.SetContext(caddyfile.MatcherNameCtxKey, matcherLabel)
			exprDispenser.Next()
			remainingArgs := 0
			for exprDispenser.NextArg() {
				remainingArgs++
			}
			for rewind := 0; rewind < remainingArgs; rewind++ {
				exprDispenser.Prev()
			}
			exprMatcher := new(caddyhttp.MatchExpression)
			if remainingArgs == 0 {
				return exprDispenser.ArgErr()
			}
			exprDispenser.NextArg()
			exprMatcher.Expr = exprDispenser.Val()
			contextName := exprDispenser.GetContextString(caddyfile.MatcherNameCtxKey)
			if contextName != "" {
				exprMatcher.Name = contextName
				encoded, err := json.Marshal(exprMatcher)
				if err != nil {
					matchers[definitionName]["expression"] = nil
				} else {
					matchers[definitionName]["expression"] = encoded
				}
			} else {
				encoded, err := json.Marshal(exprMatcher)
				if err != nil {
					matchers[definitionName]["expression"] = nil
				} else {
					matchers[definitionName]["expression"] = encoded
				}
			}
			return nil
		}
		d.Prev()
	}

	tokensByMatcherName := make(map[string][]caddyfile.Token)
	for nesting := d.Nesting(); d.NextArg() || d.NextBlock(nesting); {
		matcherName := d.Val()
		segmentTokens := []caddyfile.Token{d.Token()}
		for d.NextArg() {
			segmentTokens = append(segmentTokens, d.Token())
		}
		openedBlock := false
		for blockNesting := d.Nesting(); d.NextBlock(blockNesting); {
			if !openedBlock {
				d.Prev()
				segmentTokens = append(segmentTokens, d.Token())
				d.Next()
				openedBlock = true
